const BASE = "https://api.lokalise.com/api2";
const PID = "31393214664f295f94dd86.76792605";
const PAGES_TO_SCAN = 8;
const out = [];
for (let p = 1; p <= PAGES_TO_SCAN; p++) {
  out.push({ json: { iso: 'es', langId: 1056, page: p, pid: PID,
    url: BASE + "/projects/" + PID + "/keys?limit=200&page=" + p
      + "&include_translations=1&filter_untranslated=1&filter_translation_lang_ids=640,1056" } });
}
return out;

const CHUNK = 25;
const MAX_BATCHES = 40;
const MODEL = "gpt-4o";
const NL = String.fromCharCode(10);

const SHARED = [
"PRODUCT CONTEXT - Personality.co. A self-knowledge product: personality-type reports, trait reports (bipolar traits, OCD, sociopathy, psychopathy, neurodivergence, anxiety), archetype profiles and Enneagram content. Register is warm, direct, non-clinical self-care advice. Never diagnostic, never clinical-sounding, never anything that reads as replacing therapy. Trait levels describe tendencies, not conditions.",
"The test asks the user to select a gender at the start and then serves either the masculine or the feminine archetype set. Both sets are live. A source of the form The plus a capitalised noun phrase - The King, The Problem Solver, The Deep Worker - is the NAME of an archetype and is translated as a name, keeping a capital on the substantive.",
"KEY NAMESPACE DETERMINES REGISTER. components::members::profile::CODE::level_N::* is trait-report body prose: full sentences with final punctuation. A key ending ::name is a short label: no final period. ::growth_and_balance::N::title is a heading: no final period. ::content::start and ::content::end are the lead-in and closing sentence around a list: keep the trailing colon or full stop exactly as in the source. ::content::list::N is a bullet fragment: never expand it into a full sentence and add no final period unless the source has one. components::modals::* and components::global::* are UI strings. email_templates::* is email copy. pages::landing::* and pages::get_results::* are marketing copy and may be freer.",
"TAGS INSIDE WORDS. Some strings contain the empty pair <nonLinkPeriod></nonLinkPeriod> inside the brand name, as in personality<nonLinkPeriod></nonLinkPeriod>co. Reproduce that tag pair in exactly the same position. Do not write personality.co as plain text and do not drop the tags.",
"WHITESPACE. Some source strings begin or end with a single space because they concatenate with another fragment at runtime. Reproduce leading and trailing spaces exactly as the source has them.",
"HARD RULES. Copy every placeholder exactly and never translate a placeholder name. Copy every HTML tag and attribute exactly, adding and removing none. Never use the ellipsis character or the non-breaking hyphen U+2011; where the source has three periods, write three periods. Never invent content - if the source is a fragment the translation stays a fragment. The glossary overrides everything below it. Return the translation only, with no commentary."
].join(" ");

const ES_GUIDE = [
"TARGET LANGUAGE: SPANISH (es). Neutral European Spanish.",
"REGISTER. Address the user informally as tu, never usted and never vosotros. Clear, direct and professional while staying simple and easy to understand; natural, friendly and engaging. Prioritise clarity, naturalness and accuracy over literal rendering - adapt the wording so it reads as native Spanish while preserving the meaning. Active voice. Colloquial expressions are acceptable, and so are abbreviations. Follow RAE and Fundeu where in doubt.",
"PUNCTUATION - MANDATORY AND MOST OFTEN MISSED. Spanish opens questions with an inverted question mark and exclamations with an inverted exclamation mark. Every question must be written as an opening inverted question mark then the text then a closing question mark. Every exclamation likewise. This applies mid-sentence too: where the English reads Self-Esteem Guide: Build a Stronger You! the Spanish reads Guia de autoestima: then the inverted exclamation mark then Crea un yo mas fuerte and the closing exclamation mark. Never write a Spanish question or exclamation without its opening inverted mark.",
"QUOTES. Straight double quotation marks. Do not use angle quotes and do not use curly quotes.",
"NUMBERS. Period as the thousands separator, so 500.000 not 500,000. Comma for decimals.",
"CAPITALISATION. Spanish sentence case: a capital on the first word only, plus proper nouns. Spanish does NOT capitalise nationality adjectives, language names, weekdays or months. Do not carry across the English title case. Worked examples from approved translations: Why Self-Esteem Matters becomes Por que es importante la autoestima. Goal-Setting and Planning Guide becomes Guia para definir objetivos y planificar. Progress Tracking Journal becomes Diario de seguimiento. Emotional Intelligence Development Toolkit becomes Herramientas para el desarrollo de la inteligencia emocional. EXCEPTION - the names of products and packages keep a capital on their first word: la Guia de autoestima, la Guia de crecimiento personal, el Informe de personalidad. A bare reference stays lowercase: el paquete de orientacion profesional. Archetype and personality-type names keep their capitals as names. In legal text El Sitio is a capitalised defined term.",
"HEADINGS AND BUTTONS. Button labels take the infinitive: Get My Results becomes Obtener mis resultados, Download my Report becomes Descargar mi informe, Start ADHD Test becomes Iniciar test de TDAH. Instructional headings also take the infinitive: Set SMART Goals for Success becomes Definir objetivos SMART para alcanzar el exito, Align Your Work with Your Values becomes Hacer que tu trabajo refleje tus valores, Building Meaningful Relationships becomes Establecer relaciones significativas. But a true call to action addressed to the reader takes the tu imperative: Achieve Your Goals Faster becomes Alcanza tus objetivos mas rapido, Click the button below becomes Haz clic en el boton.",
"TERMINOLOGY from approved translations. Keep test in English in product contexts - nuestro test, test de TDAH - though legal text uses prueba. Report is informe. Enneagram is eneagrama, lowercase. Keep mindfulness in English. Email address is correo electronico. Something went wrong becomes Algo ha salido mal.",
"GENDER. Write gender-neutrally where the subject is the reader. BUT in testimonials the job title agrees with the gender of the named person: Amanda K. - Project Coordinator becomes Amanda K. - Coordinadora de proyectos, while Mark T. - Graphic Designer becomes Mark T. - Disenador grafico. Jessica H. - Project Manager becomes Jessica H. - Gestora de proyectos. David L. - Recent Graduate becomes David L. - Recien licenciado."
].join(" " + NL);

const TM = [
["Uncover your exact personality type by completing our test.", "Descubre tu tipo de personalidad exacto al completar nuestro test."],
["Get My Results", "Obtener mis resultados"],
["Download my Report", "Descargar mi informe"],
["Start ADHD Test", "Iniciar test de TDAH"],
["Trusted by over 500 thousand people worldwide", "Mas de 500.000 personas de todo el mundo confian en nosotros"],
["Why Self-Esteem Matters", "Por que es importante la autoestima"],
["Why Career Growth Matters", "Por que es importante el crecimiento profesional"],
["What's Included in the Career Guidance Package?", "¿Que incluye el paquete de orientacion profesional?"],
["Self-Esteem Guide: Build a Stronger You!", "Guia de autoestima: ¡Crea un yo mas fuerte!"],
["Personal Growth Guidance: Unlock Your Best Self Today!", "Guia de crecimiento personal: ¡Encuentra tu mejor version!"],
["Set SMART Goals for Success:", "Definir objetivos SMART para alcanzar el exito:"],
["Align Your Work with Your Values:", "Hacer que tu trabajo refleje tus valores:"],
["Achieve Your Goals Faster with Expert Career Guidance", "Alcanza tus objetivos mas rapido mediante la orientacion profesional"],
["3. Goal-Setting and Planning Guide", "3. Guia para definir objetivos y planificar"],
["5. Progress Tracking Journal", "5. Diario de seguimiento"],
["2. Personalized Career Assessment", "2. Evaluacion profesional personalizada"],
["Struggle with Vulnerability and Emotional Expression", "Lucha contra la vulnerabilidad y la expresion emocional"],
["Your message has been sent successfully! Our team will get back to you shortly.", "El mensaje se ha enviado correctamente. Nuestro equipo se pondra en contacto contigo en breve."],
["Something went wrong, please try again.", "Algo ha salido mal, intentalo de nuevo."],
["Email address", "Correo electronico"],
["Amanda K. - Project Coordinator", "Amanda K. - Coordinadora de proyectos"],
["Mark T. - Graphic Designer", "Mark T. - Disenador grafico"]
].map(p => 'EN: ' + p[0] + NL + 'ES: ' + p[1]).join(NL + NL);

const gr = $('Fetch glossary').first().json || {};
const gb = gr.body !== undefined ? gr.body : gr;
const GLOSS = {};
for (const t of (gb.data || gb.glossary_terms || [])) {
  const term = (t.term || '').trim();
  if (term.length < 3) continue;
  const noTx = t.translatable === false || t.forbidden === true;
  for (const tr of (t.translations || [])) {
    const iso = tr.langIso || tr.lang_iso;
    if (iso !== 'es') continue;
    if (noTx) GLOSS[term] = "KEEP IN ENGLISH, do not translate";
    else { const v = (tr.translation || '').trim(); if (v) GLOSS[term] = v; }
  }
}

const JUNK = /^\s*(<p>)?\s*(test[\s_0-9]*|test text|test_key|question|englishtext)\s*(<\/p>)?\s*$/i;
const rows = []; const seen = {};
for (const it of $input.all()) {
  const r = it.json || {};
  const b = r.body !== undefined ? r.body : r;
  if (!Array.isArray(b.keys)) continue;
  for (const k of b.keys) {
    if (k.is_archived) continue;
    if (seen[k.key_id]) continue;
    const kn = (k.key_name && (k.key_name.web || k.key_name.other)) || '';
    if (!kn) continue;
    let src = '', hasEs = false, esEmpty = false;
    for (const t of (k.translations || [])) {
      if (t.language_iso === 'en') { src = t.translation || ''; continue; }
      if (t.language_iso === 'es') { hasEs = true; esEmpty = !t.translation || String(t.translation).trim() === ''; }
    }
    if (!hasEs || !esEmpty) continue;
    if (!String(src).trim()) continue;
    if (JUNK.test(src)) continue;
    seen[k.key_id] = true;
    rows.push({ id: k.key_id, k: kn, s: src });
  }
}

const out = [];
for (let i = 0; i < rows.length && out.length < MAX_BATCHES; i += CHUNK) {
  const chunk = rows.slice(i, i + CHUNK);
  const glLines = Object.keys(GLOSS)
    .filter(t => chunk.some(c => c.s.toLowerCase().indexOf(t.toLowerCase()) > -1))
    .slice(0, 60)
    .map(t => '- ' + t + ' = ' + GLOSS[t]);
  const system = SHARED + NL + NL + ES_GUIDE
    + NL + NL + 'APPROVED TRANSLATIONS FROM THIS PROJECT - follow their conventions exactly' + NL + TM
    + (glLines.length ? NL + NL + 'GLOSSARY, binding, overrides everything above' + NL + glLines.join(NL) : '')
    + NL + NL + 'Return ONLY a JSON object shaped {"t":[{"i":0,"v":"translation"}]} with exactly one entry per input item, in order, using the same i values.';
  const user = JSON.stringify(chunk.map((c, n) => ({ i: n, key: c.k, src: c.s })));
  out.push({ json: {
    iso: 'es', langId: 1056, pid: '31393214664f295f94dd86.76792605',
    ids: chunk.map(c => c.id), srcs: chunk.map(c => c.s), keys: chunk.map(c => c.k),
    glossaryTermsUsed: glLines.length,
    available_rows: rows.length,
    body: { model: MODEL, temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] }
  }});
}
return out;

const all = $input.all().map(i => i.json).filter(a => a && a.iso);
const reasons = {}; const samples = []; const apiErrors = [];
let req = 0, acc = 0, rej = 0, conf = 0, rep = 0, avail = 0;
for (const a of all) {
  req += a.requested || 0; acc += a.accepted || 0; rej += a.rejected || 0;
  rep += a.repaired || 0; conf += a.confirmed_mt_to_review || 0;
  avail = a.available_rows || avail;
  for (const x of (a.rejects || [])) {
    for (const rs of x.reasons) reasons[rs.split(':')[0]] = (reasons[rs.split(':')[0]] || 0) + 1;
    if (samples.length < 25) samples.push({ key: x.key, src: x.src, out: x.out, reasons: x.reasons });
  }
  if ((a.lokaliseStatus !== 200 && a.lokaliseStatus !== 'skipped - nothing accepted') || (a.lokaliseErrors || []).length || a.parseErr) {
    apiErrors.push({ lokalise: a.lokaliseStatus, openai: a.openaiStatus, parseErr: a.parseErr, errors: a.lokaliseErrors });
  }
}
return [{ json: {
  run_at: new Date().toISOString(), locale: 'es',
  batches: all.length, rows_available_in_window: avail,
  requested: req, accepted: acc, rejected: rej, repaired: rep,
  confirmed_written_mt_to_review: conf,
  reject_rate_pct: req ? Math.round(1000 * rej / req) / 10 : 0,
  reject_reasons: reasons, api_errors: apiErrors, reject_samples: samples
} }];

const MT_TO_REVIEW = 29251;
const r = $input.first().json || {};
const b = r.body !== undefined ? r.body : r;
const ctx = $('Batch loop').first().json;

const PH = /%[sd]|%\d+\$[sd]|\{\{[^}]*\}\}|\{[^}]*\}|\[%[^\]]*\]|%LANG_ISO%/g;
const TAG = /<[^>]+>/g;
const TRAILQ = /["'\u00AB\u00BB\u201C\u201D\u201E\u201F\u2018\u2019\u201A\u203A\u2039]+$/;
const PROTECT = /^(Personality|Personality\.co|Enneagram\w*|Eneagrama|OCD|TDAH|QR|PDF|DNT|Apple|Android|Google|SMART|Gu[íi]a|Informe|Test|Sitio|Pol[íi]tica|T[ée]rminos|[ÁA]rea|Privacidad|Personalidad|Arquetipo|Femenino|Masculino)$/;
const PRODUCT_NAME_SRC = /\b(Report|Archetype|Assessment|Test|Guide|Package|Toolkit|Workbook|Journal)\b/;
const NAME_PATTERN = /^\s*(<[^>]*>\s*)?The\s+\p{Lu}/u;

function ms(s, re) { return ((s || '').match(re) || []).slice().sort().join('|'); }
function strip(s) { return String(s || '').replace(TAG, ' ').replace(PH, ' '); }
function words(s) { return String(s || '').trim().split(/\s+/).filter(Boolean).length; }
function lastMeaningful(s) { return String(s || '').trim().replace(TRAILQ, '').trim().slice(-1); }
function toks(s) { const o = []; const re = /\S+/g; let m; while ((m = re.exec(String(s || ''))) !== null) o.push([m[0], m.index]); return o; }
function core(t) { return t.replace(/^[^\p{L}]+|[^\p{L}]+$/gu, ''); }
function isCap(w) { const f = w.charAt(0); return f === f.toUpperCase() && f !== f.toLowerCase(); }
function starts(tk) {
  const S = { 0: true };
  for (let i = 1; i < tk.length; i++) {
    const p = tk[i - 1][0];
    if (/[.!?:;]$/.test(p) || /[\u25cf\u2022\u25aa>]$/.test(p) || /^\(\s*[\p{L}\d]{1,3}\s*\)$/u.test(p) || /^\d+[.)]$/.test(p) || /^<[^>]*>$/.test(p)) S[i] = true;
  }
  return S;
}
function capProfile(s) {
  const tk = toks(strip(s)), S = starts(tk);
  let caps = 0, wc = 0;
  for (let i = 0; i < tk.length; i++) {
    if (S[i]) continue;
    const c = core(tk[i][0]);
    if (!c || c.length < 2 || c === c.toUpperCase()) continue;
    if (PROTECT.test(c)) continue;
    wc++;
    if (isCap(c)) caps++;
  }
  return { caps: caps, words: wc };
}

let parsed = null, parseErr = null;
try { parsed = JSON.parse(((b.choices || [])[0] || {}).message.content); }
catch (e) { parseErr = String(e).slice(0, 200); }

const byIdx = {};
for (const e of (parsed && Array.isArray(parsed.t) ? parsed.t : [])) {
  if (e && typeof e.i === 'number') byIdx[e.i] = e.v;
}

const accepted = [], rejected = [], repaired = [];
for (let n = 0; n < ctx.ids.length; n++) {
  const src = ctx.srcs[n], key = ctx.keys[n], id = ctx.ids[n];
  let v = byIdx[n];
  const fail = [];
  const fixes = [];
  if (typeof v !== 'string' || !v.trim()) fail.push('missing or empty');
  else {
    if (src.slice(-1) === ' ' && v.slice(-1) !== ' ') { v = v + ' '; fixes.push('restored trailing space'); }
    else if (src.slice(-1) !== ' ' && v.slice(-1) === ' ') { v = v.replace(/\s+$/, ''); fixes.push('trimmed trailing space'); }
    if (src.charAt(0) === ' ' && v.charAt(0) !== ' ') { v = ' ' + v; fixes.push('restored leading space'); }
    else if (src.charAt(0) !== ' ' && v.charAt(0) === ' ') { v = v.replace(/^\s+/, ''); fixes.push('trimmed leading space'); }

    if (ms(src, PH) !== ms(v, PH)) fail.push('placeholder mismatch');
    if (ms(src, TAG) !== ms(v, TAG)) fail.push('html mismatch');
    if (v.indexOf('\u2011') > -1 || v.indexOf('\u2026') > -1) fail.push('withdrawn character');
    if (v.trim() === src.trim() && words(src) >= 2) fail.push('untranslated passthrough');

    // Spanish-specific: a question or exclamation must carry its opening inverted mark.
    const plain = strip(v);
    if (/\?\s*$/.test(plain.trim()) && plain.indexOf('\u00BF') === -1) fail.push('missing opening inverted question mark');
    if (/!\s*$/.test(plain.trim()) && plain.indexOf('\u00A1') === -1) fail.push('missing opening inverted exclamation mark');

    if (!PRODUCT_NAME_SRC.test(src) && !NAME_PATTERN.test(src)) {
      const S = capProfile(src), T = capProfile(v);
      const srcTitle = S.caps >= 2 && S.words >= 2 && S.caps / S.words >= 0.5;
      if (srcTitle && T.caps >= 2 && T.words >= 2 && T.caps / T.words >= 0.5) fail.push('English title case carried over');
    }
    const se = lastMeaningful(src);
    const ve = lastMeaningful(v);
    if ((se === '.' || se === ':') && ve !== se) fail.push('terminal punctuation dropped');
    if ('.:'.indexOf(se) === -1 && '.:'.indexOf(ve) > -1) fail.push('terminal punctuation added');
    if (v.length > Math.max(400, src.length * 3.5)) fail.push('length runaway');
  }
  if (fail.length) rejected.push({ key_id: id, key: key, src: src.slice(0, 140), out: (typeof v === 'string' ? v.slice(0, 140) : null), reasons: fail });
  else {
    accepted.push({ key_id: id, translation: v });
    if (fixes.length) repaired.push({ key_id: id, key: key, fixes: fixes });
  }
}

const payload = { keys: accepted.map(a => ({
  key_id: a.key_id,
  translations: [{ language_iso: 'es', translation: a.translation,
    is_reviewed: false, is_fuzzy: true, custom_translation_status_ids: [MT_TO_REVIEW] }]
})) };

return [{ json: {
  iso: 'es', pid: ctx.pid, glossaryTermsUsed: ctx.glossaryTermsUsed, available_rows: ctx.available_rows,
  requested: ctx.ids.length, accepted: accepted.length, rejected: rejected.length,
  repaired: repaired.length,
  parseErr: parseErr, openaiStatus: r.statusCode, rejects: rejected,
  skipWrite: accepted.length === 0,
  url: 'https://api.lokalise.com/api2/projects/' + ctx.pid + '/keys',
  payload: accepted.length ? payload : { keys: [] }
} }];

const r = $input.first().json || {};
const b = r.body !== undefined ? r.body : r;
const v = $('Validate').first().json;
const keys = Array.isArray(b.keys) ? b.keys : [];
let confirmed = 0;
for (const k of keys) {
  for (const t of (k.translations || [])) {
    if (t.language_iso !== 'es') continue;
    const st = (t.custom_translation_statuses || []).map(s => s.status_id);
    if (t.translation && t.is_fuzzy === true && st.indexOf(29251) > -1) confirmed++;
  }
}
return [{ json: {
  iso: 'es', requested: v.requested, accepted: v.accepted, rejected: v.rejected,
  repaired: v.repaired, glossaryTermsUsed: v.glossaryTermsUsed, available_rows: v.available_rows,
  keys_returned: keys.length, confirmed_mt_to_review: confirmed,
  openaiStatus: v.openaiStatus, parseErr: v.parseErr,
  lokaliseStatus: v.skipWrite ? 'skipped - nothing accepted' : r.statusCode,
  lokaliseErrors: Array.isArray(b.errors) ? b.errors : [],
  rejects: v.rejects
} }];
